# Full-precision pi accessors (take the first N limbs of the generated table,
# mirroring _ln_2 in src/log.jl).
@inline _pi(::Type{_MF{Float32,N}}) where {N} =
    _MF{Float32,N}(ntuple(i -> _PI_FULL_F32[i], Val{N}()))
@inline _pi(::Type{_MF{Float64,N}}) where {N} =
    _MF{Float64,N}(ntuple(i -> _PI_FULL_F64[i], Val{N}()))

# pi/2 is just pi with each limb exponent decremented (exact); no separate table.
@inline _half_pi(::Type{_MF{T,N}}) where {T,N} = unsafe_ldexp(_pi(_MF{T,N}), -1)

