@generated _atan_polynomial(x::NTuple{N,T}) where {N,T} =
    _horner_expr_mf(_atan_coefficients(T, Val{N}()))

@inline _val(::Val{K}) where {K} = K

# Half-angle reduction: r <- r / (1 + sqrt(1 + r^2)), applied K times.
@inline _atan_reduce(r::_MF{T,N}, ::Val{0}) where {T,N} = r
@inline function _atan_reduce(r::_MF{T,N}, ::Val{K}) where {T,N,K}
    _one = one(_MF{T,N})
    next = r / (_one + sqrt(_one + r * r))
    return _atan_reduce(next, Val(K - 1))
end

@inline function Base.atan(x::_MF{T,N}) where {T,N}
    p = precision(_MF{T,N})
    hp = _half_pi(_MF{T,N})
    af = abs(first(x._limbs))
    _one = one(_MF{T,N})
    a = abs(x)
    big = a > _one
    r = ifelse(big, _one / a, a)                      # r in [0, 1]
    # For r <= tmax, evaluate directly: forming 1+r^2 with a small r
    # discards the low bits of r^2 and corrupts the reduced value.
    kv = _atan_halvings(T, Val(N))                    # Val{K}()
    in_range = first(r._limbs) > _atan_tmax(T, Val(N))
    t = ifelse(in_range, _atan_reduce(r, kv), r)      # t in [0, tmax]
    k = ifelse(in_range, _val(kv), 0)
    u = mfsqr(t._limbs, Val(N))                       # t^2
    q = _MF{T,N}(_atan_polynomial(u))                 # Q(t^2); P = 1 + t^2*Q
    base = unsafe_ldexp(t + t * (_MF{T,N}(u) * q), k) # 2^k * (t + t^3*Q)
    mag = ifelse(big, _half_pi(_MF{T,N}) - base, base)
    return ifelse(signbit(x), -mag, mag)
end

@inline function Base.atan(y::_MF{T,N}, x::_MF{T,N}) where {T,N}
    _zero = zero(_MF{T,N})
    pi_ = _pi(_MF{T,N})
    hp = _half_pi(_MF{T,N})

    # Divide the smaller magnitude by the larger so the ratio stays in [-1, 1]
    # When swapped, use atan(y/x) = sign(y/x)*pi/2 - atan(x/y).
    swap = abs(y) > abs(x)
    a = atan(ifelse(swap, x, y) / ifelse(swap, y, x))   # in [-pi/4, pi/4]
    ratio_neg = signbit(x) ⊻ signbit(y)
    base = ifelse(swap, ifelse(ratio_neg, -hp, hp) - a, a)

    # Quadrant: x < 0 shifts by +-pi (x == 0, y != 0 is handled by the swap).
    result = ifelse(signbit(x), base + ifelse(signbit(y), -pi_, pi_), base)
    # Origin: atan(+-0, +0) = +-0 ; atan(+-0, -0) = +-pi.
    origin = ifelse(signbit(x),
        ifelse(signbit(y), -pi_, pi_),
        ifelse(signbit(y), -_zero, _zero))
    return ifelse(iszero(x) & iszero(y), origin, result)
end
